      <div class="sc-tracks" aria-label="三条学习路线">${tracks.map(track=>`<button type="button" data-sc-track="${esc(track.id)}" class="${state.track===track.id?'active':''}"><strong>${esc(track.title)}</strong><span>${esc(track.summary)}</span><small>进入学习路线 →</small></button>`).join('')}</div>
