    $('#sc-learn-track').onchange=e=>{state.track=e.target.value;draw();};
    root.querySelectorAll('[data-sc-lesson]').forEach(button=>button.onclick=()=>{state.lesson=Number(button.dataset.scLesson);drawLearn();$('.sc-lesson h2')?.scrollIntoView({block:'nearest'});});
